    q("8", "في أي مدينة يمنية تاريخية اتخذت الملكة أروى الصليحية عاصمة لملكها وشيدت جامعها الكبير؟", "جبلة", "صنعاء", "زبيد", "تعز"),
    q("8", "من هي السيدة المسلمة التي أسست جامعة القرويين في فاس عام 859م كأقدم جامعة عاملة في العالم؟", "فاطمة الفهرية", "مريم الفهرية", "زبيدة بنت جعفر", "ست الشام"),
    q("8", "من هي شقيقة فاطمة الفهرية التي قامت ببناء مسجد الأندلس الشهير في مدينة فاس بالمغرب؟", "مريم الفهرية", "عائشة الفهرية", "زينب النفزاوية", "كنزة الأوربية"),
    q("8", "من هي السيدة الأمازيغية النبيلة زوجة يوسف بن تاشفين ومهندسة تأسيس مدينة مراكش ودولة المرابطين؟", "زينب النفزاوية", "فاطمة الفهرية", "السيدة الحرة", "كنزة الأوربية"),
    q("8", "من هي حاكمة تطوان وأميرة الجهاد البحري في غرب البحر المتوسط بالقرن السادس عشر الملقبة بـ \"السيدة الحرة\"؟", "عائشة العلمي (السيدة الحرة)", "زينب النفزاوية", "خناثة بنت بكار", "كنزة الأوربية"),
    q("8", "من هي السيدة العباسية زوجة الخليفة هارون الرشيد التي اشتهرت بحفر آبار درب الحج من الكوفة لمكة؟", "زبيدة بنت جعفر", "الخيزران", "قطر الندى", "شغب"),
    q("8", "من هي السيدة الجليلة زوجة النبي محمد ﷺ وأول من آمنت برسالته وساندته بأموالها وقلبها؟", "خديجة بنت خويلد", "عائشة بنت أبي بكر", "حفصة بنت عمر", "أم سلمة"),
    q("8", "من هي السيدة الملقبة بـ \"فقيهة الأمة\" وأكثر النساء رواية للحديث النبوي الشريف عن رسول الله ﷺ؟", "عائشة بنت أبي بكر", "أم سلمة", "أسماء بنت أبي بكر", "فاطمة الزهراء"),
    q("8", "من هي ابنة رسول الله ﷺ الملقبة بـ \"الزهراء\" وسيدة نساء أهل الجنة وزوجة الإمام علي بن أبي طالب؟", "فاطمة الزهراء", "زينب بنت محمد", "رقية بنت محمد", "أم كلثوم بنت محمد"),
    q("8", "من هي الصحابية الجليلة الملقبة بـ \"ذات النطاقين\" وابنة الصديق وأخت عائشة وأم عبد الله بن الزبير؟", "أسماء بنت أبي بكر", "أم عمارة", "خولة بنت الأزور", "نسيبة المازنية"),
    q("8", "من هي الصحابية المجاهدة الشجاعة (أم عمارة) التي دافعت عن رسول الله بالسيف في غزوة أحد؟", "نسيبة بنت كعب", "خولة بنت الأزور", "رفيدة الأسلمية", "أم حرام بنت ملحان"),
    q("8", "من هي أول طبيبة وممرضة في تاريخ الإسلام التي نصبت خيمة لعلاج الجرحى في الغزوات؟", "رفيدة الأسلمية", "كعيبة بنت سعد", "أم عمارة", "الشفاء بنت عبد الله"),
    q("8", "من هي الصحابية الجليلة التي أدارت الحسبة والأسواق في المدينة المنورة بتكليف من الخليفة عمر بن الخطاب؟", "الشفاء بنت عبد الله", "أم رومان", "أسماء بنت عميس", "أم حكيم"),
    q("8", "من هي الشاعرة المخضرمة من بني سليم الملقبة بـ \"الخنساء\" والتي اشتهرت برثاء شقيقيها صخر ومعاوية؟", "تماضر بنت عمرو", "ليلى الأخيلية", "عمرة بنت مرداس", "سكينة بنت الحسين"),
    q("8", "في أي عام ميلادي افتتحت مدرسة السنية للبنات في القاهرة كأول مدرسة حكومية لتعليم البنات في العالم العربي؟", "1873", "1882", "1865", "1890"),
    q("8", "من هي أول فتاة مصرية وعربية تحصل على شهادة الثانوية العامة (البكالوريا) عام 1907 وتدير مدرسة؟", "نبوية موسى", "هدى شعراوي", "سهير القلماوي", "ملك حفني ناصف"),
    q("8", "من هي أول طبيبة في مصر والعالم العربي تخرجت من كلية الطب في بريطانيا عام 1930؟", "هيلانة سيداروس", "توحيدة عبد الرحمن", "كوكب حفني ناصف", "عزيزة حسين"),
    q("8", "من هي أول كابتن طيار امرأة في العالم العربي ومصر تقود طائرة منفردة من لندن إلى القاهرة عام 1933؟", "لطيفة النادي", "عزيزة محرم", "ليندا أمين", "كابتن سحر"),
    q("8", "من هي أول عالمة ذرة مصرية لقبت بـ \"موس كوري الشرق\" واغتيلت في أمريكا عام 1952 في ظروف غامضة؟", "سميرة موسى", "سميرة إسلام", "عزيزة كمال", "نجوى عبد المجيد"),
    q("8", "من هي أول امرأة مصرية وعربية تتولى عمادة كلية جامعية (كلية الآداب بجامعة القاهرة) ورائدة الدراسات الأدبية؟", "سهير القلماوي", "بنت الشاطئ", "درية شفيق", "أمينة السعيد"),
    q("8", "من هي المفكرة والأديبة المصرية الكبيرة المعروفة بلقب \"بنت الشاطئ\" وصاحبة التفسير البياني للقرآن الكريم؟", "عائشة عبد الرحمن", "سهير القلماوي", "نبوية موسى", "ملك حفني ناصف"),
  ];

  print("Total questions created: ${questions.length}");

  final Map<String, int> countsByLevel = {};
  for (final item in questions) {
    final lvl = item["Level"] as String;
    countsByLevel[lvl] = (countsByLevel[lvl] ?? 0) + 1;
  }

  print("Counts by level:");
  countsByLevel.keys.toList()..sort()..forEach((k) => print("  Level $k: ${countsByLevel[k]}"));

  final expected = {
    "0": 34,
    "1": 33,
    "2": 33,
    "4": 33,
    "5": 33,
    "6": 34,
    "3": 33,
    "7": 33,
    "8": 34,
  };

  expected.forEach((lvl, expectedCount) {
    final actual = countsByLevel[lvl] ?? 0;
    if (actual != expectedCount) {
      throw Exception("Level $lvl count mismatch: expected $expectedCount, got $actual");
    }
  });

  final tier0 = (countsByLevel["0"] ?? 0) + (countsByLevel["1"] ?? 0) + (countsByLevel["2"] ?? 0);
  final tier1 = (countsByLevel["4"] ?? 0) + (countsByLevel["5"] ?? 0) + (countsByLevel["6"] ?? 0);
  final tier2 = (countsByLevel["3"] ?? 0) + (countsByLevel["7"] ?? 0) + (countsByLevel["8"] ?? 0);
  print("Tier 0 total: $tier0 (expected 100)");
  print("Tier 1 total: $tier1 (expected 100)");
  print("Tier 2 total: $tier2 (expected 100)");

  assert(tier0 == 100);
  assert(tier1 == 100);
  assert(tier2 == 100);

  final Set<String> questionTexts = {};
  int leakCount = 0;
  for (int i = 0; i < questions.length; i++) {
    final qItem = questions[i];
    final qText = qItem["Q"] as String;
    final r = qItem["R"] as String;
    final w1 = qItem["W1"] as String;
    final w2 = qItem["W2"] as String;
    final w3 = qItem["W3"] as String;

    if (!qText.endsWith("؟")) {
      throw Exception("Question #$i does not end with '؟': $qText");
    }

    if (qText.contains("اكتب الرقم") || qText.contains("اختر ") || qText.contains("اختر:") || qText.contains("ما رأيك")) {
      throw Exception("Question #$i contains forbidden phrase: $qText");
    }

    if (questionTexts.contains(qText)) {
      throw Exception("Duplicate question found at #$i: $qText");
    }
    questionTexts.add(qText);

    final set = {r, w1, w2, w3};
    if (set.length != 4) {
      throw Exception("Question #$i has duplicate options: R='$r', W1='$w1', W2='$w2', W3='$w3'");
    }

    // Leak check (R appearing inside Q):
    bool leak = false;
    if (r.length > 3 && qText.contains(r)) {
      leak = true;
    }
    if (leak) {
      print("Potential leak in #$i: Q='$qText' contains R='$r'");
      leakCount++;
    }
  }

  print("Total distinct questions: ${questionTexts.length}");
  print("Potential leaks: $leakCount");
  if (leakCount > 0) {
    throw Exception("Leaks found! Please resolve before continuing.");
  }

  // Write JSON to file
  final jsonStr = JsonEncoder.withIndent("  ").convert(questions);
  final outFile = File("assets/questions_girls_300.json");
  outFile.writeAsStringSync(jsonStr, encoding: utf8);
  print("Successfully saved 300 questions to ${outFile.path}");
}
